Create Table.code:
// Create a table if it does not already exist.
query(`
  CREATE TABLE IF NOT EXISTS facility_reports (
    facility_code STRING,
    period STRING,
    indicator STRING,
    value INT
  )
  STORED AS PARQUET
`);

Insert Rows.code:
// Insert one row per incoming report value.
query(
  `INSERT INTO facility_reports VALUES ${$.data.values
    .map(v => `('${v.facilityCode}', '${v.period}', '${v.indicator}', ${v.value})`)
    .join(', ')}`
);

Get Recent Records.code:
// Select rows newer than a date passed in the payload.
query(
  `SELECT patient_id, facility_code, visit_date FROM anc_visits WHERE visit_date >= '${$.data.since}' LIMIT 1000`
);
